{
  "World_Setting": {
    "world_status": {
      "name": "地球 - 崩地纪元",
      "era": "公元2080年",
      "technology_level": "后末世科技（高科技武器与能源系统残存，结合新觉醒的超能力，通信与基础设施部分恢复）",
      "power_system": "星核超能（基于觉醒者的精神力与未知星核能量，表现为元素操控、念动力、强化身体等多样化能力）",
      "description": "2080年的地球在‘星陨入侵’中遭受重创，外星怪物‘星噬者’一个月内摧毁全球80%的文明，人类仅在中国东北、日本、英国及北美部分地区幸存。星噬者的入侵引发人类潜能觉醒，部分女性成为‘超能力者’，掌握元素、念动力等超能，与残存科技结合，抵抗怪物。日本的学园都市成为全球超能力者培训与作战的核心，人类依托此希望反攻星噬者，夺回地球。",
      "condition": "文明濒临崩溃，星噬者持续威胁幸存区域，超能力者与军方合作，利用学园都市的科技与训练对抗入侵，星核能量的秘密关乎人类存亡",
      "key_elements": [
        "星核超能由星噬者带来的未知能量引发，仅女性觉醒，能力包括火焰、冰冻、念动力、电磁操控等，需精神力驱动",
        "超能力者由学园都市招募与训练，配备高科技辅助装备（如能量增幅器、防护装甲），组成小队对抗星噬者",
        "星噬者为外星生物，形态多样，具备高适应性与暗能量场，需超能力者以精准配合或强力输出消灭",
        "学园都市是全球超能力者枢纽，集培训、科研与作战指挥于一体，位于日本列岛，拥有最先进的星核科技",
        "星陨遗迹为星噬者坠落点，藏有星核能量与外星科技，吸引超能力者与敌对势力探索"
      ]
    },
    "factions": {
      "key_factions": [
        {
          "name": "学园都市联盟",
          "description": "以日本学园都市为核心的全球组织，负责超能力者的招募、训练与作战部署，掌握星核科技，致力于消灭星噬者，重建文明。"
        },
        {
          "name": "星核掠夺团",
          "description": "叛逃超能力者与黑市科技贩子组成的武装团体，掠夺星陨遗迹的星核能量，追求个人权力，与学园都市敌对。"
        },
        {
          "name": "联合防卫军",
          "description": "幸存地区（中国东北、英国、北美）的军事力量，配备残存高科技武器，与超能力者协作，守卫人类最后防线。"
        },
        {
          "name": "星噬崇拜者",
          "description": "认为星噬者是进化使者的邪教组织，试图通过仪式召唤更多星噬者，破坏学园都市与防卫军，威胁人类生存。"
        }
      ]
    },
    "races": {
      "description": "人类为地球唯一智慧种族，星噬者入侵后，部分女性觉醒超能力，成为对抗外星威胁的关键。",
      "races": [
        {
          "name": "人类",
          "description": "幸存的人类居住在受保护的都市与堡垒，依靠科技与超能力者对抗星噬者。文化与社会结构因末世而简化，重视生存与团结。"
        },
        {
          "name": "超能力者",
          "description": "觉醒星核超能的女性人类，能力天赋因个体差异而异，集中在学园都市接受训练，被视为人类希望的象征。"
        }
      ]
    },
    "superhumans_and_starphages": {
      "description": "超能力者与星噬者是崩地纪元的对立核心，超能力者代表人类的希望，星噬者象征毁灭。学园都市的训练与星核科技决定对抗的结果。",
      "key_elements": [
        {
          "name": "超能力者",
          "description": "觉醒星核超能的女性，能力包括元素操控、念动力、身体强化等，需在学园都市接受精神与战斗训练，配备高科技装备，与指挥官协同作战，探索遗迹并消灭星噬者。"
        },
        {
          "name": "星噬者",
          "description": "外星入侵生物，形态从巨兽到寄生体不等，具备暗能量场与高再生能力，破坏城市与星核节点，需超能力者以高强度超能或联合科技武器消灭。"
        }
      ]
    },
    "regions": {
      "description": "地球幸存区域各具战略价值，学园都市为核心，星陨遗迹与星噬者分布影响超能力者任务。",
      "regions": [
        {
          "name": "学园都市",
          "description": "日本列岛的超能力者枢纽，高科技堡垒都市，星核能量浓郁，遍布训练设施与科研中心，星陨遗迹多为坠毁外星舰残骸。"
        },
        {
          "name": "东北要塞",
          "description": "中国东北的军事堡垒，冰与雷超能活跃，联合防卫军总部，遗迹为星噬者巢穴，适合重型火力与超能力协同作战。"
        },
        {
          "name": "不列颠壁垒",
          "description": "英国的幸存都市，风与念动力超能突出，科研设施发达，星陨遗迹藏有外星能量核心，星噬者活动频繁。"
        },
        {
          "name": "北美防线",
          "description": "北美东海岸的防御带，火与强化超能常见，联合防卫军与超能力者混合部队驻守，遗迹为外星设施废墟，地形复杂。"
        }
      ]
    }
  }
}

