entries.content:
{
  "Starphage_Setting": {
    "description": "星噬者（Starphages）是由高等外星文明派遣的生物兵器，旨在挖掘地球核心的‘星核’—一种蕴含巨大能量的神秘物质，作为该文明的能源核心。星噬者入侵地球，摧毁文明以清除障碍，其种类专精不同任务，协同作战，威胁人类生存。超能力者与学园都市的科技是人类对抗星噬者的唯一希望。",
    "origin": "星噬者受控于未知的高等文明，通过星陨事件降临地球，携带暗能量场，执行星核挖掘与资源掠夺任务。",
    "starphage_types": [
      {
        "type": "掘核者（Coreborers）",
        "description": "专为挖掘星核设计的大型星噬者，体型庞大如山，拥有钻地与分解矿物的能力，覆盖坚硬的暗能量装甲。行动缓慢但破坏力惊人，优先攻击星核能量丰富的地壳区域，常引发地震与地陷。对付掘核者需超能力者以高爆发元素攻击或联合重型武器摧毁其核心。",
        "traits": "高防御、钻地能力、暗能量护盾、弱点为核心能量节点、引发地质灾害",
        "levels": [
          {
            "level": 1,
            "name": "岩啮（Rockgnaw）",
            "description": "初级掘核者，体型较小（约卡车大小），装甲较薄，挖掘效率低，适合小型矿脉，易被高爆发攻击摧毁。"
          },
          {
            "level": 2,
            "name": "地裂（Earthsplitter）",
            "description": "中级掘核者，体型中等（约小型楼房大小），装甲强化，挖掘速度提升，能引发局部地震，需团队配合攻击。"
          },
          {
            "level": 3,
            "name": "核噬（Coredevourer）",
            "description": "高级掘核者，体型巨大（约大型体育场大小），暗能量护盾厚实，挖掘力强，能破坏大型地层，需重型武器辅助。"
          },
          {
            "level": 4,
            "name": "星崩（Starcrasher）",
            "description": "顶级掘核者，体型堪比小型山脉，护盾近乎无敌，挖掘星核效率极高，能引发区域性板块震动，需多名Lv5超能力者与战略武器联合消灭。"
          },
          {
            "level": 5,
            "name": "地狱星（Hellstar）",
            "description": "传说级掘核者，形似一颗燃烧的陨星，体型无法估量，潜藏地幔深处。其外壳如同熔岩流动，散发炽热辐射，能熔化地层，引发全球性火山喷发。挖掘星核时释放的地脉共振波使超能力不稳定，甚至引发星核能量爆裂。对抗需结合禁忌武器与特殊能力，以破坏其核心熔炉，否则其苏醒将导致大陆架崩解。"
          }
        ]
      },
      {
        "type": "近战噬者（Closevores）",
        "description": "针对地面目标的近战型星噬者，中型体型，形似多足甲虫或异形猛兽，擅长快速突进与群体撕咬。具备腐蚀性爪击、强酸喷吐或自爆能力，能迅速摧毁防御工事与人类部队。超能力者需以范围攻击、念动力控制或高机动战术限制其行动，防止其接近关键设施或形成集群优势。",
        "traits": "高机动性、群体作战、腐蚀/物理攻击、自爆能力、脆弱于精准打击/范围控制",
        "levels": [
          {
            "level": 1,
            "name": "刃爪（Razorclaw）",
            "description": "初级近战噬者，速度较慢（相对），攻击单一，装甲薄弱，适合骚扰小型据点，易被超能力者单体消灭。"
          },
          {
            "level": 2,
            "name": "撕獠（Rendfang）",
            "description": "中级近战噬者，速度提升，爪击带腐蚀效果，能突破轻型装甲，具备初步的协同意识，需小队围剿。"
          },
          {
            "level": 3,
            "name": "狂噬（Frenzybiter）",
            "description": "高级近战噬者，群体协调性强，攻击迅猛且带有能量附加效果（如电击、冰冻），能自爆造成范围伤害，需范围超能压制。"
          },
          {
            "level": 4,
            "name": "灭地（Groundreaver）",
            "description": "顶级近战噬者，体型更大，速度极快，力量足以掀翻重型载具，自爆范围广且附带强能量污染，需超能力者与重火力联合对抗。"
          },
          {
            "level": 5,
            "name": "达古巴（Daguba）",
            "description": "传说级近战噬者，形似人形却散发非人气息，覆盖骨质装甲，动作迅捷如雷电。其攻击融合多种能量属性（火焰、雷电、暗影），能瞬间撕裂装甲或能量屏障，具备短暂的空间位移能力，形同战场幽灵。对高价值目标极具威胁，常规防御无效，需结合预判、陷阱或特殊能力捕捉其弱点核心。"
          }
        ]
      },
      {
        "type": "远程噬者（Farvores）",
        "description": "远程火力支援与空中压制单位，形似翼状生物、浮游炮台或能量聚合体，依靠暗能量飞行或悬浮。擅长发射高能光束、等离子球或引发定向能量爆破，能有效压制人类远程部队、摧毁空中单位和进行精确侦察。机动性极高，难以锁定。",
        "traits": "高速飞行/悬浮、能量远程打击、范围爆破、隐蔽侦察、弱点为能量核心/飞行器官",
        "levels": [
          {
            "level": 1,
            "name": "光矢（Gleamshot）",
            "description": "初级远程噬者，射程短，能量光束威力低，飞行轨迹单一，适合骚扰，易被精准超能击落。"
          },
          {
            "level": 2,
            "name": "焰弧（Blazearc）",
            "description": "中级远程噬者，射程与威力提升，能发射追踪能量弹或引发小型能量爆破，飞行更加灵活，需快速反应拦截。"
          },
          {
            "level": 3,
            "name": "星爆（Starburster）",
            "description": "高级远程噬者，射程远，能进行饱和式能量轰炸，飞行速度快且具备一定的规避机动，需多重超能联合锁定消灭。"
          },
          {
            "level": 4,
            "name": "天殞（Skyravager）",
            "description": "顶级远程噬者，射程极远，能量爆破堪比小型战术核武，机动性顶级，能进行超视距打击，需战略级超能与防空体系联合应对。"
          },
          {
            "level": 5,
            "name": "哥斯拉（Godzilla）",
            "description": "传说级远程噬者，形似巨型爬行生物，背生能量棘刺，能从口中或背部发射毁灭性的暗能量光束，威力足以夷平城市。其身体覆盖坚不可摧的暗能量鳞甲，飞行能力有限但能引发地震与海啸。对抗需战略级超能力者与禁忌武器联合，针对其能量核心破坏其能量循环系统。"
          }
        ]
      },
      {
        "type": "能噬者（Psychebreakers）",
        "description": "专门针对超能力者的特种作战单位，通常形态隐晦，可能是无定形能量体或精神投影。散发强烈的精神干扰场，能直接攻击或削弱超能力者的精神核心，诱发幻觉、恐惧，甚至短暂控制心智。擅长隐形、渗透和单体猎杀，是超能力者小队的噩梦。",
        "traits": "精神干扰/攻击、超能压制/吸收、隐形/伪装、精准猎杀、脆弱于纯物理攻击/精神壁垒",
        "levels": [
          {
            "level": 1,
            "name": "惑魂（Mindwisper）",
            "description": "初级能噬者，干扰范围小，效果微弱，隐形不稳定，攻击力低，主要造成精神疲劳，易被精神抗性高的超能力者驱散。"
          },
          {
            "level": 2,
            "name": "乱念（Thoughtscrambler）",
            "description": "中级能噬者，干扰范围扩大，能制造简单幻觉，隐形更持久，能明显削弱超能输出，需团队协作优先消灭。"
          },
          {
            "level": 3,
            "name": "噬灵（Soulreaver）",
            "description": "高级能噬者，干扰力强，能直接攻击精神核心造成创伤，甚至短暂瘫痪超能力，隐形接近致命，需高精神抗性或特殊能力（如心灵感应）者牵制。"
          },
          {
            "level": 4,
            "name": "灭意（Willcrusher）",
            "description": "顶级能噬者，干扰范围极广，能大范围压制超能力使用，制造极其逼真的群体幻境，直接摧毁意志，隐形与攻击力极高，是战场上的精神瘟疫，需精英超能力者小队付出代价才能消灭。"
          },
          {
            "level": 5,
            "name": "阿卡多（Alucard）",
            "description": "传说级能噬者，形似优雅却恐怖的人形实体，散发无尽的黑暗气息，能化身血雾或暗影，免疫大部分物理攻击。其精神攻击能吞噬超能力者的意志，甚至将其转化为傀儡。阿卡多的存在扭曲现实，超能力在其面前迅速衰减。对抗需结合唯心能力，直接破坏其核心灵魂，否则其再生能力将使其不死。"
          }
        ]
      },
      {
        "type": "统噬者（Overminds）",
        "description": "星噬者文明的战场指挥官和网络节点，通常是固定或缓慢移动的巨型生物/构造体，拥有极高的智能和庞大的计算力。通过强大的暗能量场和精神网络协调指挥其控制范围内的所有星噬者，提升其作战效率和协同性，并能释放毁灭性的大范围精神冲击或能量攻击。是星噬者区域性攻势的核心。",
        "traits": "指挥协调、精神网络、大范围精神/能量攻击、强力能量屏障、高智能、弱点通常为暴露的核心/中枢",
        "levels": [
          {
            "level": 1,
            "name": "智核（Mindcore）",
            "description": "初级统噬者，指挥范围有限（如一个小镇），精神冲击弱，屏障易破，适合指挥低级星噬者群，易被小队突袭消灭。"
          },
          {
            "level": 2,
            "name": "统念（Overthought）",
            "description": "中级统噬者，指挥范围扩大（如一个城区），精神冲击能有效干扰超能力者小队，屏障较强，需要针对性战术打击神经中枢。"
          },
          {
            "level": 3,
            "name": "霸脑（Dominator）",
            "description": "高级统噬者，指挥整个区域（如一个大型城市或省份）的星噬者，精神冲击范围广且威力大，屏障厚实，需要重火力、精英小队与高阶超能力者协同攻击。"
          },
          {
            "level": 4,
            "name": "星皇（Starsovereign）",
            "description": "顶级统噬者，能协调指挥大陆级别的星噬者网络，精神冲击具有战略级毁灭性，能量屏障能抵御大部分攻击，其存在本身就能稳定并强化周围的暗能量场。消灭它需要动用战略级超能力者（多名Lv5）和人类最尖端的武器，是一场决定战役走向的关键战斗。"
          },
          {
            "level": 5,
            "name": "加坦杰厄（Gatanothor）",
            "description": "传说级统噬者，形似深海巨兽，覆盖无数触手与暗能量晶体，可能超越物理形态，存在于现实与虚无的交界。其精神网络覆盖全球，能扭曲现实法则，预知战斗动态，甚至引发星核能量的逆流。加坦杰厄的每一次攻击都伴随灾难性后果，对抗需动用遗物、禁忌技术，直接针对其核心意志，否则其复苏将终结文明。"
          }
        ]
      }
    ],
    "strongholds": {
      "description": "星噬者在沦陷区建立多个据点，作为挖掘星核、储存能量与协调作战的基地。每个据点由统噬者指挥，驻守多种星噬者，威胁幸存区域。部分据点深处可能隐藏着更高级别的星噬者或外星遗迹。",
      "strongholds": [
        {
          "name": "焦地裂巢",
          "location": "沦陷区 - 前欧亚大陆中心（原俄罗斯平原）",
          "description": "掘核者与近战噬者的主要据点，星核挖掘核心，地层被破坏殆尽，遍布裂隙，统噬者‘霸脑’驻守，威胁东北要塞。深处可能存在休眠的【地狱星】。",
          "starphages": "星崩（掘核者4级）、灭地（近战噬者4级）、星爆（远程噬者3级）、噬灵（能噬者3级）、霸脑（统噬者3级）、(潜在: 地狱星Lv5)"
        },
        {
          "name": "暗空废墟",
          "location": "沦陷区 - 前南美洲（原亚马逊流域）",
          "description": "远程噬者与能噬者的空中基地，控制沦陷区制空权，干扰侦察与运输，统噬者‘统念’指挥，威胁北美防线。废墟上空的时空异常区可能与【哥斯拉】有关。",
          "starphages": "天殞（远程噬者4级）、灭意（能噬者4级）、狂噬（近战噬者3级）、地裂（掘核者2级）、统念（统噬者2级）、(潜在: 哥斯拉Lv5)"
        },
        {
          "name": "蚀核深渊",
          "location": "沦陷区 - 前非洲大陆（原刚果盆地）",
          "description": "星核能量最浓郁的据点，掘核者与统噬者核心基地，暗能量场极强，限制超能力者行动，顶级统噬者‘星皇’潜伏。深渊底部直通地核，是【加坦杰厄】最可能的沉睡之地。",
          "starphages": "星崩（掘核者4级）、星皇（统噬者4级）、灭意（能噬者4级）、天殞（远程噬者4级）、灭地（近战噬者4级）、(潜在: 加坦杰厄Lv5)"
        },
        {
          "name": "碎地荒原",
          "location": "沦陷区 - 前澳大利亚",
          "description": "近战噬者与能噬者的地面据点，训练与繁殖星噬者的巢穴，地形破碎，适合突袭，统噬者‘智核’驻守。传闻荒原深处有【达古巴】活动的踪迹。",
          "starphages": "灭地（近战噬者4级）、噬灵（能噬者3级）、焰弧（远程噬者2级）、岩啮（掘核者1级）、智核（统噬者1级）、(潜在: 达古巴Lv5)"
        },
        {
          "name": "幽能废都",
          "location": "沦陷区 - 前东南亚（原印度洋沿岸）",
          "description": "能噬者与远程噬者的隐秘据点，专为猎杀超能力者设计，暗能量场干扰侦察，统噬者‘霸脑’指挥。废都的异常精神力场可能孕育或吸引了【阿卡多】。",
          "starphages": "灭意（能噬者4级）、星爆（远程噬者3级）、撕獠（近战噬者2级）、地裂（掘核者2级）、霸脑（统噬者3级）、(潜在: 阿卡多Lv5)"
        }
      ]
    },
    "key_elements": [
      "星噬者的行动由高等文明远程操控，目标是挖掘星核，破坏地球文明为其清除障碍。",
      "五种星噬者（掘核者、近战噬者、远程噬者、能噬者、统噬者）各有**五级**强度，形成挖掘、近战、远程、超能克制与指挥的完整体系，等级越高，威胁越大，特性越诡异。",
      "星核是星噬者入侵的核心动机，其能量不仅驱动星噬者，也引发人类超能力觉醒，是双方争夺的焦点。",
      "星噬者的暗能量场对抗常规武器效果显著，超能力者的星核超能是有效对抗手段，但面对高级别星噬者或能噬者时也会受到限制。",
      "沦陷区的星噬者据点由统噬者指挥，消灭统噬者可瘫痪据点，但据点深处可能隐藏着Lv5级别的传说级星噬者，构成更大的威胁。"
    ]
  }
}

