entries.content:
{
  "Invasion_Rules": {
    "description": "在崩地纪元（公元2080年），星噬者作为高等外star文明的生物兵器，持续威胁学园都市及人类幸存区域。其入侵遵循特定规律，迫使学园都市采取防御与反攻并重的策略。学园都市联合中国、英国、美国、日本的残存军队，定期对抗星噬者入侵并尝试收复沦陷区，维护人类生存希望。",
    "rules": [
      {
        "rule": "周期性入侵",
        "description": "星噬者每隔一周（7天）从沦陷区的据点（如焦地裂巢、蚀核深渊）发起一次针对学园都市的入侵。入侵规模与强度随机，取决于统噬者的指挥与星核能量波动，可能为小规模骚扰（低级近战噬者与远程噬者）或大规模攻势（包含掘核者与高级能噬者）。"
      },
      {
        "rule": "入侵模式",
        "description": "入侵通常由近战噬者与远程噬者打头阵，突破学园都市边境防卫区的星核屏障，随后能噬者针对超能力者展开猎杀，掘核者破坏星核塔等关键设施。统噬者隐藏幕后，通过暗能量场协调行动，高级入侵可能出现Lv3-Lv4统噬者直接指挥。"
      },
      {
        "rule": "学园都市防御机制",
        "description": "学园都市依靠星核屏障、AI监控系统与联合防卫军巡逻队抵御入侵。超能力者（Lv1-Lv5）按等级分配防御任务：Lv1-Lv2负责外围骚扰清理，Lv3-Lv4对抗主力星噬者，Lv5与暗部处理高威胁目标（如掘核者、统噬者）。星辉学院实时调度，通过星核增幅器与战术装备提升战力。"
      },
      {
        "rule": "主动出击",
        "description": "学园都市不定期组织主动出击，联合中国（玄武会）、英国（时钟塔）、美国（曙光团）、日本（星核院）的军队与超能力者小队，针对沦陷区的星噬者据点（如碎地荒原、幽能废都）展开收复作战。目标包括破坏星核挖掘设施、消灭统噬者、回收星陨遗迹中的外星科技。"
      },
      {
        "rule": "联合收复作战",
        "description": "收复作战由学园都市理事会协调，四国军队提供重型火力（星核驱动的炮台、无人机群）与后勤支援，超能力者负责突袭与精准打击。作战通常以小规模试探开始，成功削弱据点后转为全面进攻。Lv5超能力者与暗部是关键战力，负责直面高级星噬者与统噬者。"
      },
      {
        "rule": "入侵与反攻后果",
        "description": "星噬者入侵若被击退，学园都市可获得短暂喘息，但星核塔可能受损，需紧急修复。失败可能导致边境防卫区沦陷，威胁居民区。主动出击若成功，可削弱星噬者据点，回收星核资源，提升人类士气；失败则损失超能力者与装备，延长下一次入侵的准备周期。"
      }
    ],
    "key_elements": [
      "星噬者入侵的周期性（每周一次）迫使学园都市保持高度戒备，资源与超能力者调度需精准高效",
      "入侵强度与星噬者种类（掘核者、近战噬者、远程噬者、能噬者、统噬者）相关，高级统噬者的出现大幅提升威胁",
      "学园都市的星核屏障与超能力者是防御核心，Lv5超能力者与暗部决定重大战斗胜负",
      "主动出击需四国军队与超能力者协同，收复沦陷区是长期战略目标，但高风险高回报",
      "星核资源的争夺是入侵与反攻的核心，影响学园都市的能源供应与超能力者装备开发"
    ]
  }
}

